package com.nexusdrive.auth.entity; import com.nexusdrive.common.enums.Role; import jakarta.persistence.*; import java.time.*; import java.util.UUID; @Entity @Table(name="users") public class User {@Id private UUID id=UUID.randomUUID();@Column(nullable=false,unique=true,length=50)private String username;@Column(nullable=false,unique=true)private String email;@Column(name="password_hash",nullable=false)private String passwordHash;@Enumerated(EnumType.STRING)@Column(nullable=false)private Role role;@Column(name="failed_login_attempts",nullable=false)private int failedLoginAttempts;@Column(name="locked_until")private Instant lockedUntil;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@PrePersist void pre(){createdAt=updatedAt=Instant.now();if(role==null)role=Role.USER;}@PreUpdate void upd(){updatedAt=Instant.now();}public UUID getId(){return id;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}public int getFailedLoginAttempts(){return failedLoginAttempts;}public void setFailedLoginAttempts(int v){failedLoginAttempts=v;}public Instant getLockedUntil(){return lockedUntil;}public void setLockedUntil(Instant v){lockedUntil=v;}}
